<?php
require 'config/database.php';
$page=$_GET['page']??'matching'; $message='';
function h($v){return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function slots($pdo,$employee,$date,$hours){$a=$pdo->prepare('SELECT start_time,end_time FROM employee_availability WHERE employee_id=? AND available_date=?');$a->execute([$employee,$date]);$busy=$pdo->prepare('SELECT start_time,end_time FROM schedules WHERE employee_id=? AND schedule_date=? ORDER BY start_time');$busy->execute([$employee,$date]);$busy=$busy->fetchAll();$out=[];foreach($a as $w){$cur=strtotime("$date {$w['start_time']}");$last=strtotime("$date {$w['end_time']}");foreach($busy as $b){$bs=strtotime("$date {$b['start_time']}");$be=strtotime("$date {$b['end_time']}");if($be<=$cur||$bs>=$last)continue;if($bs-$cur>=$hours*3600)$out[]=[date('H:i',$cur),date('H:i',$cur+$hours*3600)];$cur=max($cur,$be);}if($last-$cur>=$hours*3600)$out[]=[date('H:i',$cur),date('H:i',$cur+$hours*3600)];}return $out;}
if(isset($_POST['save_schedule'])){$check=$pdo->prepare('SELECT COUNT(*) FROM schedules WHERE employee_id=? AND schedule_date=? AND start_time<? AND end_time>?');$check->execute([$_POST['employee'],$_POST['date'],$_POST['end'],$_POST['start']]);if($check->fetchColumn())$message='Conflict found. Choose another slot.';else{$pdo->prepare('INSERT INTO schedules(employee_id,task_id,schedule_date,start_time,end_time) VALUES(?,?,?,?,?)')->execute([$_POST['employee'],$_POST['task'],$_POST['date'],$_POST['start'],$_POST['end']]);$message='Schedule saved successfully.';}}
$employees=$pdo->query('SELECT * FROM employees ORDER BY name')->fetchAll();$tasks=$pdo->query("SELECT * FROM tasks WHERE status<>'Completed' ORDER BY title")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><title>Employee Decision Support</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-primary"><div class="container"><a class="navbar-brand" href="index.php">Employee Decision Support</a><div><a class="btn btn-sm btn-light" href="?page=matching">Matching</a> <a class="btn btn-sm btn-light" href="?page=scheduling">Scheduling</a> <a class="btn btn-sm btn-light" href="?page=bottleneck">Bottleneck</a></div></div></nav><main class="container py-4"><?php if($message):?><div class="alert alert-info"><?=h($message)?></div><?php endif;?>
<?php if($page==='matching'): $taskId=(int)($_GET['task']??0); ?><h2>Employee–Task Matching</h2><p>Select a task. Score = Skill 50 + Availability 30 + Workload 20.</p><form class="card card-body mb-4"><input type="hidden" name="page" value="matching"><select name="task" class="form-select mb-2" required><option value="">Select task</option><?php foreach($tasks as $t):?><option value="<?=$t['id']?>" <?=$taskId==$t['id']?'selected':''?>><?=h($t['title'])?> — <?=h($t['required_skill'])?></option><?php endforeach;?></select><button class="btn btn-primary">Find Best Employee</button></form><?php if($taskId):$q=$pdo->prepare('SELECT * FROM tasks WHERE id=?');$q->execute([$taskId]);$task=$q->fetch();$results=[];foreach($employees as $e){$skills=strtolower($e['skills']);$skill=str_contains($skills,strtolower($task['required_skill']))?50:0;$availability=$e['availability_status']==='Available'?30:($e['availability_status']==='Partially Available'?15:0);$workload=$e['workload']<40?20:($e['workload']<=70?10:0);$results[]=[$e['name'],$skill,$availability,$workload,$skill+$availability+$workload];}usort($results,fn($a,$b)=>$b[4]<=>$a[4]);?><table class="table table-bordered bg-white"><tr><th>Employee</th><th>Skill</th><th>Availability</th><th>Workload</th><th>Total</th></tr><?php foreach($results as $i=>$r):?><tr class="<?=$i===0?'table-success':''?>"><td><?=h($r[0])?> <?=$i===0?'(Best match)':''?></td><td><?=$r[1]?></td><td><?=$r[2]?></td><td><?=$r[3]?></td><td><?=$r[4]?>/100</td></tr><?php endforeach;?></table><?php endif;?>
<?php elseif($page==='scheduling'): $eid=(int)($_POST['employee']??0);$tid=(int)($_POST['task']??0);$date=$_POST['date']??'2026-09-08';$free=[];if(isset($_POST['find'])){$q=$pdo->prepare('SELECT estimated_hours FROM tasks WHERE id=?');$q->execute([$tid]);$free=slots($pdo,$eid,$date,(int)$q->fetchColumn());}?><h2>Smart Scheduling</h2><form method="post" class="card card-body"><input type="hidden" name="page" value="scheduling"><select name="employee" class="form-select mb-2"><option>Select employee</option><?php foreach($employees as $e):?><option value="<?=$e['id']?>"><?=h($e['name'])?></option><?php endforeach;?></select><select name="task" class="form-select mb-2"><option>Select task</option><?php foreach($tasks as $t):?><option value="<?=$t['id']?>"><?=h($t['title'])?> (<?=$t['estimated_hours']?> hours)</option><?php endforeach;?></select><input type="date" name="date" class="form-control mb-2" value="<?=h($date)?>"><button name="find" class="btn btn-primary">Find Free Slots</button></form><?php foreach($free as $s):?><form method="post" class="card card-body mt-2"><strong><?=$s[0]?> to <?=$s[1]?></strong><input type="hidden" name="page" value="scheduling"><input type="hidden" name="employee" value="<?=$eid?>"><input type="hidden" name="task" value="<?=$tid?>"><input type="hidden" name="date" value="<?=h($date)?>"><input type="hidden" name="start" value="<?=$s[0]?>"><input type="hidden" name="end" value="<?=$s[1]?>"><button name="save_schedule" class="btn btn-success mt-2">Save this slot</button></form><?php endforeach;?>
<?php else:$rows=$pdo->query('SELECT * FROM tasks')->fetchAll();$stages=['Created → Assigned'=>[],'Assigned → Started'=>[],'Started → Completed'=>[]];foreach($rows as $r){if($r['assigned_at'])$stages['Created → Assigned'][]=(strtotime($r['assigned_at'])-strtotime($r['created_at']))/3600;if($r['started_at'])$stages['Assigned → Started'][]=(strtotime($r['started_at'])-strtotime($r['assigned_at']))/3600;if($r['completed_at'])$stages['Started → Completed'][]=(strtotime($r['completed_at'])-strtotime($r['started_at']))/3600;}$avg=[];foreach($stages as $n=>$v)$avg[$n]=count($v)?round(array_sum($v)/count($v),1):0;arsort($avg);?><h2>Workflow Bottleneck Detection</h2><div class="alert alert-warning">Potential bottleneck: <b><?=h(array_key_first($avg))?></b> — <?=reset($avg)?> average hours</div><table class="table bg-white"><tr><th>Stage</th><th>Average hours</th></tr><?php foreach($avg as $n=>$v):?><tr><td><?=h($n)?></td><td><?=$v?></td></tr><?php endforeach;?></table><?php endif;?></main></body></html>
